#include "covariance.hpp"

using num_t = DATA_TYPE;

namespace {

constexpr auto i_vec = noarr::vector<'i'>();
constexpr auto j_vec = noarr::vector<'j'>();
constexpr auto k_vec = noarr::vector<'k'>();

struct tuning {
	// data: k x j  (N samples, M features)
	// We choose layout k_vec ^ j_vec so that the sample dimension 'k'
	// is the innermost (contiguous) dimension. This makes all reductions
	// over k (which dominate the runtime in the covariance phase) walk
	// contiguous memory.
	DEFINE_PROTO_STRUCT(data_layout, k_vec ^ j_vec);

	// cov:  i x j  (M x M), row-major: 'j' is innermost
	DEFINE_PROTO_STRUCT(cov_layout, j_vec ^ i_vec);

	// mean: j      (M), contiguous in 'j'
	DEFINE_PROTO_STRUCT(mean_layout, j_vec);
} tuning;

// initialization function
void init_array(num_t &float_n, auto data) {
	// data: k x j  (k ~ N, j ~ M)
	using namespace noarr;

	// float_n = N (number of samples)
	float_n = (num_t)(data | get_length<'k'>());

	auto m_len = data | get_length<'j'>();

	// With data_layout = k_vec ^ j_vec, the innermost dimension is 'k'.
	// We still want to initialize data[k,j] for all k,j; using j-outer,
	// k-inner gives contiguous writes in 'k'.
	traverser(data).template for_dims<'j'>([=](auto tj) {
		tj.template for_each<'k'>([=](auto state) {
			auto [k, j] = get_indices<'k', 'j'>(state);
			data[state] = (num_t)(k * j) / (num_t)m_len;
		});
	});
}

// computation kernel
[[gnu::flatten, gnu::noinline]]
void kernel_covariance(num_t float_n, auto data, auto cov, auto mean) {
	// data: k x j  (N samples, M features), layout k_vec ^ j_vec
	// cov:  i x j  (M x M), row-major (i outer, j inner)
	// mean: j      (M)
	using namespace noarr;

	// view of data where the feature dimension is called 'i'
	// (for cov's row index); data_i: i x k (same memory as data)
	auto data_i = data ^ noarr::rename<'j', 'i'>();

	// Precompute reciprocals to replace many divisions by cheaper multiplies
	const num_t inv_float_n      = (num_t)1.0 / float_n;
	const num_t inv_n_minus_1    = (num_t)1.0 / (float_n - (num_t)1.0);

#pragma scop
	// ---------------------------------------------------------------------
	// 1) mean[j] = (1/n) * sum_k data[k][j]
	//
	// We exploit that, with data_layout = k_vec ^ j_vec, 'k' is the
	// innermost (contiguous) dimension. We therefore iterate with 'j'
	// fixed and reduce over k, so that data[k,j] is accessed with
	// stride 1 in memory.
	// ---------------------------------------------------------------------

	// 1a) initialize mean[j] = 0
	traverser(mean).for_each([=](auto s) {
		mean[s] = (num_t)0;
	});

	// 1b) accumulate sums over all samples
	traverser(data, mean).template for_dims<'j'>([=](auto tj) {
		// tj has 'j' fixed; we now iterate over all k for this feature
		tj.template for_each<'k'>([=](auto s) {
			// s contains both 'j' and 'k'
			// mean[s] uses only 'j', ignoring 'k'
			mean[s] += data[s];
		});
	});

	// 1c) normalize by float_n: mean[j] *= 1/float_n
	traverser(mean).for_each([=](auto s) {
		mean[s] *= inv_float_n;
	});

	// ---------------------------------------------------------------------
	// 2) Center each feature: data[k][j] -= mean[j]
	//
	// Again, we keep 'j' fixed and iterate over k, so that for each
	// feature j we stream through all samples k contiguously.
	// We hoist mean[j] out of the inner loop for better reuse.
	// ---------------------------------------------------------------------
	traverser(data, mean).template for_dims<'j'>([=](auto tj) {
		// tj has 'j' fixed
		const num_t m_j = mean[tj];

		// For this feature j, subtract its mean from every sample k
		tj.template for_each<'k'>([=](auto s) {
			data[s] -= m_j;
		});
	});

	// ---------------------------------------------------------------------
	// 3) Covariance:
	//
	//    For centered data:
	//      cov[i][j] = (1 / (float_n - 1)) * sum_k data[k][i] * data[k][j]
	//      cov[j][i] = cov[i][j]  (symmetry)
	//
	// We keep the mathematically simple i–j–k structure, but:
	//   - thanks to data_layout = k_vec ^ j_vec and the rename to data_i,
	//     all k-reductions now walk contiguous memory in both data and
	//     data_i;
	//   - we accumulate in a local scalar 'acc' to avoid repeatedly
	//     reading/writing cov[i][j] inside the k-loop.
	// ---------------------------------------------------------------------
	traverser(cov, data, data_i).template for_dims<'i'>([=](auto ti) {
		// ti has 'i' fixed; remaining dims are 'j' and 'k'
		ti.template for_dims<'j'>([=](auto tij) {
			auto s_ij = tij.state();
			auto [i_idx, j_idx] = get_indices<'i', 'j'>(s_ij);

			// enforce j >= i (upper triangle, including diagonal)
			if (j_idx < i_idx)
				return;

			// local accumulator to keep cov[i][j] in a register
			num_t acc = (num_t)0;

			// accumulate over k (samples); 'k' is the innermost and
			// contiguous dimension for both data and data_i
			tij.template for_each<'k'>([=, &acc](auto sk) {
				acc += data[sk] * data_i[sk];
			});

			// normalize once and write back
			const num_t value = acc * inv_n_minus_1;
			cov[s_ij] = value;

			// symmetry: cov[j][i] = cov[i][j]
			if (j_idx > i_idx) {
				auto s_ji = noarr::idx<'i', 'j'>(j_idx, i_idx);
				cov[s_ji] = value;
			}
		});
	});
#pragma endscop
}

