void kernel_covariance(num_t float_n, auto data, auto cov, auto mean) {
	// data: k x j  (N samples, M features)
	// cov:  i x j  (M x M)
	// mean: j      (M)
	using namespace noarr;
	using noarr::lit;

	// view of data where the feature dimension is called 'i'
	// (for cov's row index); data_i: k x i
	auto data_i = data ^ noarr::rename<'j', 'i'>();

	// Precompute reciprocals to replace per-element divisions.
	const num_t inv_float_n = num_t(1.0) / float_n;
	const num_t inv_n_minus_1 = num_t(1.0) / (float_n - num_t(1.0));

	// Tile sizes for covariance in i and j (features).
	// Kept modest and compile-time so the compiler can unroll and vectorize.
	constexpr std::size_t tile_i = 32;
	constexpr std::size_t tile_j = 32;

#pragma scop
	// ---------------------------------------------------------------------
	// 1) mean[j] = (1/n) * sum_k data[k][j]
	//
	// We reorganize the loops to stream rows of data (k outer, j inner),
	// which is cache-friendly for the row-major layout (k outer, j inner).
	// ---------------------------------------------------------------------

	// 1a) Initialize mean[j] to zero
	traverser(mean).for_each([&](auto s) {
		mean[s] = (num_t)0;
	});

	// 1b) Accumulate sums over all samples
	//     for k:
	//       for j:
	//         mean[j] += data[k,j]
	traverser(data, mean).template for_dims<'k'>([&](auto tk) {
		tk.template for_each<'j'>([&](auto state) {
			mean[state] += data[state];
		});
	});

	// 1c) Scale by 1/float_n
	traverser(mean).for_each([&](auto s) {
		mean[s] *= inv_float_n;
	});

	// ---------------------------------------------------------------------
	// 2) Center data in place: data[k][j] -= mean[j]
	//
	// We keep the original orientation (k outer, j inner), which streams
	// each sample row and reuses mean[j] from cache.
	// ---------------------------------------------------------------------
	traverser(data, mean).template for_dims<'k'>([&](auto tk) {
		tk.template for_each<'j'>([&](auto state) {
			data[state] -= mean[state];
		});
	});

	// ---------------------------------------------------------------------
	// 3) Covariance:
	//      for 0 <= i <= j < M:
	//        cov[i][j] = sum_k data[k][i] * data[k][j] / (float_n - 1)
	//        cov[j][i] = cov[i][j]
	//
	// We tile in i and j using into_blocks_dynamic, keeping k as a simple
	// reduction dimension. The traversal order becomes:
	//   for each J (tile of j)
	//     for each I (tile of i)
	//       for each (i,j) in that tile:
	//         [if j < i: skip]
	//         reduce over k
	//
	// This improves locality of writes to cov and keeps the semantics
	// identical to the original triple loop (i, j, k).
	// ---------------------------------------------------------------------

	// Build a proto-structure that splits i and j into tiles:
	//   i -> (I, i) with guard dimension 's'
	//   j -> (J, j) with guard dimension 't'
	// The presence dimensions 's' and 't' ensure that partial tiles at the
	// matrix edges are handled correctly; the traverser will not execute the
	// body for out-of-bounds (i,j) pairs.
	auto tiled_order =
		noarr::into_blocks_dynamic<'i', 'I', 'i', 's'>(lit<tile_i>) ^
		noarr::into_blocks_dynamic<'j', 'J', 'j', 't'>(lit<tile_j>());

	traverser(cov, data, data_i)
		.order(tiled_order)
		// J: tile index over covariance columns
		.template for_dims<'J'>([&](auto tJ) {
			// I: tile index over covariance rows
			tJ.template for_dims<'I'>([&](auto tJI) {
				// Within this (I, J) tile, iterate valid (i, j) pairs.
				// The presence dims 's' and 't' automatically skip
				// incomplete elements in edge tiles.
				tJI.template for_dims<'i', 's', 'j', 't'>([&](auto tij) {
					auto s_ij = tij.state();
					auto [i_idx, j_idx] = get_indices<'i', 'j'>(s_ij);

					// Enforce upper triangle (including diagonal).
					if (j_idx < i_idx)
						return;

					// Accumulate over k (samples) for this (i, j)
					num_t sum = (num_t)0;

					tij.template for_each<'k'>([&](auto sk) {
						sum += data[sk] * data_i[sk];
					});

					const num_t value = sum * inv_n_minus_1;

					// Write cov[i][j]
					cov[s_ij] = value;

					// Symmetry: cov[j][i] = cov[i][j]
					// For diagonal entries (i == j) this just stores
					// the same location twice, which is harmless.
					if (j_idx != i_idx) {
						auto s_ji = noarr::idx<'i', 'j'>(j_idx, i_idx);
						cov[s_ji] = value;
					}
				});
			});
		});
#pragma endscop
}

