	// (for cov's row index); data_i: k x i
	// Note: this is a pure re-interpretation of the layout, no data is copied.
	auto data_i = data ^ noarr::rename<'j', 'i'>();

#pragma scop
	// ------------------------------------------------------------
	// 1) Compute per-feature means:
	//      mean[j] = (1 / float_n) * sum_k data[k][j]
	//
