	// 3) Covariance:
	//
	// After centering, we want:
	//   for 0 <= i <= j < M:
	//     cov[i][j] = (1 / (float_n - 1)) * sum_k data[k,i] * data[k,j]
	//     cov[j][i] = cov[i][j]
