				// exploit symmetry: compute only upper triangle (including diagonal)
				if (j_idx < i_idx)
					return;

				// data[k][j]: contiguous across j for fixed k
				const num_t x_kj = data[s];

				// s contains extra 'k' dimension, which is ignored by `cov`
				cov[s] += x_ki * x_kj;
			});
		});
	});

